	\begin{align*}
		&(\mathsf{ALine},X) \,\text{---}\, (\mathsf{Point},X)\;, &&(\mathsf{DLine},X) \,\text{---}\, (\mathsf{Point},X)\;, &&(\mathsf{Point},X) \,\text{---}\, (\mathsf{Pauli},X)\;,\\
