		&(\mathsf{Point},X) \,\text{---}\, (\mathsf{Pair},X)\;, &&(\mathsf{Pair},X) \,\text{---}\, \mathsf{Pair}\;, &&\\
		&(\mathsf{Point},Z) \,\text{---}\, (\mathsf{Pair},Z)\;, &&(\mathsf{Pair},Z) \,\text{---}\, \mathsf{Pair}\;; &&
