+\begin{lemma}[Formalization support for extensionality of finite distributions]\label{lem:distribution-ext-support-weight}
+	\lean{MIPStarRE.QPBT.Distribution.ext_of_support_of_weight}
+	\leanok
+	Two finite distributions with the same support and the same weight at every point are equal.
+\end{lemma}
+\begin{proof}
+	\leanok
+	A finite distribution is determined by its finite support and weight function, so equality of these data gives equality of the distributions.
+\end{proof}
+
+\begin{lemma}[Formalization support for composed push-forwards]\label{lem:distribution-map-map}
+	\lean{MIPStarRE.QPBT.Distribution.map_map}
+	\leanok
+	\uses{lem:distribution-ext-support-weight}
+	Let $\mu$ be a finite distribution on $A$, and let $e\colon A \to B$ and $f\colon B \to C$. Then $f_*(e_*\mu) = (f \circ e)_*\mu$.
+\end{lemma}
+\begin{proof}
+	\leanok
+	\uses{lem:distribution-ext-support-weight}
+	The two distributions have the same image support. At each $c \in C$, both weights are the sum of $\mu(a)$ over the fiber $\{a : f(e(a))=c\}$.
