+\end{lemma}
+\begin{proof}
+	\leanok
+	This is the defining weight of the uniform distribution on a finite nonempty set.
+\end{proof}
+
+\begin{lemma}[Formalization support for uniform push-forwards with equicardinal fibers]\label{lem:uniform-distribution-map-equi-cardinal-fibers}
+	\lean{MIPStarRE.QPBT.uniformDistribution_map_of_card_fiber}
+	\leanok
